#!/system/bin/sh
# Seeds deterministic JotDrop test notes for Baseline Profile generation and
# scroll measurements. Run as the shell user: sh seed-notes.sh [vault-dir]
# Shared by BaselineProfileGenerator (piped to sh) and manual measurements.
VAULT="${1:-/sdcard/Documents/JotDropBaseline}"
NOTES="$VAULT/Mini Notes"
rm -rf "$VAULT"
mkdir -p "$NOTES/.attachments"
cat > "$NOTES/.attachments/photo.b64" <<'PNG'

PNG
COLORS="default red orange yellow green teal blue purple pink brown gray"
i=1
while [ $i -le 90 ]; do
  n=$(printf '%03d' $i)
  f="$NOTES/Note $n.md"
  c=$(echo $COLORS | cut -d' ' -f$(( (i % 11) + 1 )))
  pinned=false
  [ $i -le 3 ] && pinned=true
  {
    echo '---'
    echo "color: $c"
    [ "$pinned" = true ] && echo 'pinned: true'
    [ $((i % 4)) -eq 0 ] && echo "tags: [work, idea-$((i % 5))]"
    echo '---'
    case $((i % 7)) in
      0) echo "# Groceries $n"; echo; echo "Milk, bread, eggs and coffee for the week. #shopping"; echo "Also check the pharmacy on the way back home." ;;
      1) echo "# Checklist $n"; echo; echo '- [ ] Call the plumber about the kitchen tap'; echo '- [x] Pay the electricity bill'; echo '- [ ] Book train tickets for Friday'; echo '- [ ] Return library books'; echo '- [x] Water the plants' ;;
      2) echo "# Meeting notes $n"; echo; echo "Discussed the roadmap for the next quarter. We agreed to ship the sync improvements first, then the import tools."; echo; echo "Action items were assigned to everybody, follow up next week with a short status update and a demo of the new cards."; echo; echo "Open questions: pricing, onboarding, and how to explain end-to-end encryption in plain words." ;;
      3) echo "https://example.com/articles/how-to-take-better-notes-$n"; echo; echo "Saved from the web. Read later on the train." ;;
      4) echo "## Ideas $n"; echo; echo "- **Bold idea**: a calmer home screen"; echo "- *Italic thought*: fewer buttons"; echo "- Plain bullet with a #hashtag and \`inline code\`"; echo; echo "> Quote: write it down before it is gone." ;;
      5) echo "Photo note $n"; echo; echo "![[photo-$n.png]]"; echo; echo "Whiteboard from the workshop." ;;
      6) echo "Quick thought $n: remember to stretch every hour and drink water." ;;
    esac
  } > "$f"
  if [ $((i % 7)) -eq 5 ]; then
    base64 -d "$NOTES/.attachments/photo.b64" > "$NOTES/.attachments/photo-$n.png"
  fi
  i=$((i + 1))
done
rm "$NOTES/.attachments/photo.b64"
echo "seeded $(ls "$NOTES" | grep -c '\.md$') notes in $NOTES"
